    out=[r[:] for r in grid]
    # Solid monochromatic rectangular patches, embedded in noise, are converted to 4.
    h,w=len(grid),len(grid[0])
    for r1 in range(h):
        for c1 in range(w):
            color=grid[r1][c1]
            c2=c1
            while c2+1<w and grid[r1][c2+1]==color: c2+=1
            r2=r1
            while r2+1<h and all(grid[r2+1][c]==color for c in range(c1,c2+1)): r2+=1
            if (r2-r1+1)*(c2-c1+1)>=20 and (r2-r1+1)>=4 and (c2-c1+1)>=4:
                for r in range(r1,r2+1):
                    for c in range(c1,c2+1): out[r][c]=4
    return out

